package cl.duoc.tienda.carrito.service;
import cl.duoc.tienda.carrito.dto.*; import cl.duoc.tienda.carrito.model.*; import cl.duoc.tienda.carrito.repository.*; import java.util.*; import org.slf4j.*; import org.springframework.stereotype.Service;
@Service public class CarritoService { private static final Logger log=LoggerFactory.getLogger(CarritoService.class); private final CarritoRepository repo; public CarritoService(CarritoRepository r){repo=r;} public List<Carrito> listar(){return repo.findAll();} public Carrito buscar(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Carrito no encontrado: "+id));} public Carrito guardar(CarritoRequest d){ Carrito e=new Carrito(d.usuarioId(), d.productoId(), d.cantidad()); log.info("Guardando carrito"); return repo.save(e);} public Carrito actualizar(Long id,CarritoRequest d){buscar(id); Carrito e=new Carrito(d.usuarioId(), d.productoId(), d.cantidad()); e.setId(id); return repo.save(e);} public void eliminar(Long id){buscar(id);repo.deleteById(id);log.info("Carrito eliminado: {}",id);} }
